// Monthly ministry calendar. Records are saved only after explicit confirmation.
let ministryPerson='mine',ministryMonth='',ministryPin='',ministryReport=null,ministryRequest=0;
const MINISTRY_GEM='<svg viewBox="0 0 64 64" aria-hidden="true"><defs><linearGradient id="gem-fill" x1="0" x2="1" y1="0" y2="1"><stop stop-color="#e8f7ee"/><stop offset=".5" stop-color="#a5cfca"/><stop offset="1" stop-color="#9286b9"/></linearGradient></defs><path d="M11 22 20 10h24l9 12-21 31Z" fill="url(#gem-fill)" stroke="#718f89" stroke-width="1.7" stroke-linejoin="round"/><path d="m11 22 42 0M20 10l6 12 6 31 6-31 6-12M26 22l6-12 6 12" fill="none" stroke="#fff" stroke-opacity=".65" stroke-width="1.3"/></svg>';
function ministryView(){if(!ministryMonth)ministryMonth=todayLocal().month;if(!ministryPin){ministryUnlock();return}ministryLoad()}
function ministryUnlock(){ministryReport=null;showProtectedUnlock('ministry',async (password,form)=>{let result;try{result=await ministryRead(ministryPerson,ministryMonth,password)}catch(err){throw Error(ministryError(err))}if(!form.isConnected||location.hash!=='#/ministry')return;ministryPin=password;routinePin=password;ministryReport=result;ministryRender()})}
function ministryError(err){return err.code==='PGRST202'?'봉사 보고 저장 공간을 먼저 설정해 주세요.':(err.message||'연결 상태를 확인해 주세요.')}
async function ministryRead(person,month,password=ministryPin){const r=await rpc('study_ministry_read',{p_password:password,p_person:person,p_month:month});if(!r?.ok)throw Error(r?.error||'불러오지 못했습니다.');return r}
async function ministryLoad(person=ministryPerson,month=ministryMonth){
 const token=++ministryRequest,old=document.querySelector('.ministry'),calendar=old?.querySelector('.ministry-calendar');
 document.querySelector('.ministry-loading-overlay')?.remove();document.querySelector('.ministry-load-error')?.remove();
 if(calendar){const overlay=document.createElement('div');overlay.className='ministry-loading-overlay';calendar.append(overlay);showCoupleLoading(overlay);old.setAttribute('aria-busy','true')}
 else showCoupleLoading();
 try{const result=await ministryRead(person,month);if(token!==ministryRequest||location.hash!=='#/ministry')return;ministryPerson=person;ministryMonth=month;ministryReport=result;ministryRender()}
 catch(err){if(token!==ministryRequest||location.hash!=='#/ministry')return;if(old?.isConnected){old.removeAttribute('aria-busy');old.querySelector('.ministry-loading-overlay')?.remove();const notice=document.createElement('div');notice.className='ministry-load-error';notice.setAttribute('role','alert');notice.textContent=ministryError(err)+' ';const retry=document.createElement('button');retry.type='button';retry.className='link';retry.textContent='다시 시도';retry.onclick=()=>ministryLoad(person,month);notice.append(retry);old.querySelector('.ministry-calendar').after(notice)}else{$('#app').innerHTML=`<div class="notice" role="alert">${esc(ministryError(err))} <button class="link" id="ministry-retry">다시 시도</button></div><a class="back bottom-back" href="#/home">← 처음</a>`;$('#ministry-retry').onclick=()=>ministryLoad(person,month)}}
}
function ministryRender(){if(!ministryReport)return;const [y,m]=ministryMonth.split('-').map(Number),today=todayLocal(),start=new Date(y,m-1,1).getDay(),count=monthDays(ministryMonth),hours=ministryReport.hours||{},sum=Object.values(hours).reduce((n,v)=>n+(Number(v)||0),0);const days=Array(start).fill('<span class="ministry-empty" aria-hidden="true"></span>').concat(Array.from({length:count},(_,i)=>{let d=i+1,h=Number(hours[d]||0),isToday=today.month===ministryMonth&&today.day===d;return `<button type="button" class="ministry-day${isToday?' is-today':''}" data-ministry-day="${d}" aria-label="${y}년 ${m}월 ${d}일, ${h?h+'시간':'기록 없음'}"><span class="ministry-date">${d}</span><span class="ministry-hours">${h||''}</span></button>`}));$('#app').innerHTML=`<div class="workspace ministry"><div class="ministry-head"><h1 class="people-title">봉사 보고</h1><div class="filters ministry-people" aria-label="사용자 선택">${['mine','bora'].map(p=>`<button type="button" data-ministry-person="${p}" aria-pressed="${p===ministryPerson}" class="${p===ministryPerson?'active':''}">${personIdentity(p)}</button>`).join('')}</div></div><div class="routine-month ministry-month"><button type="button" class="month-arrow" id="ministry-prev" aria-label="이전 달">${UI_CHEVRON_LEFT}</button><label class="month-picker"><span aria-hidden="true">${y}년 ${m}월</span>${UI_CHEVRON_DOWN}<input type="month" id="ministry-month" value="${ministryMonth}" min="1900-01" max="9998-12" aria-label="연도와 월 선택"></label><button type="button" class="month-arrow" id="ministry-next" aria-label="다음 달">${UI_CHEVRON_RIGHT}</button></div>${today.month!==ministryMonth?'<button type="button" class="ministry-today" id="ministry-today">이번 달</button>':''}<div class="ministry-weekdays" aria-hidden="true">${['일','월','화','수','목','금','토'].map(d=>`<span>${d}</span>`).join('')}</div><div class="ministry-calendar" aria-label="${y}년 ${m}월 봉사 시간">${days.join('')}</div><div class="ministry-summary"><div><span>봉사 시간</span><strong>${sum}시간</strong></div><button type="button" id="ministry-studies" aria-label="성서 연구 건수 수정"><span>성서 연구</span><span><strong>${ministryReport.studies===null?'—':ministryReport.studies+'건'}</strong>${UI_PENCIL}</span></button></div></div><a class="back bottom-back" href="#/home">← 처음</a>`;document.querySelectorAll('[data-ministry-person]').forEach(b=>b.onclick=()=>{if(ministryPerson===b.dataset.ministryPerson)return;ministryLoad(b.dataset.ministryPerson,ministryMonth)});$('#ministry-prev').onclick=()=>ministryChangeMonth(shiftMonth(ministryMonth,-1));$('#ministry-next').onclick=()=>ministryChangeMonth(shiftMonth(ministryMonth,1));$('#ministry-month').onchange=e=>{const next=e.target.value;e.target.value=ministryMonth;ministryChangeMonth(next)};$('#ministry-today')?.addEventListener('click',()=>ministryChangeMonth(todayLocal().month));document.querySelectorAll('[data-ministry-day]').forEach(b=>b.onclick=()=>{if(!document.querySelector('.ministry[aria-busy="true"]'))ministryDayDialog(Number(b.dataset.ministryDay),b)});$('#ministry-studies').onclick=e=>ministryStudiesDialog(e.currentTarget)}
function ministryChangeMonth(value){if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(value)||Number(value.slice(0,4))<1900||Number(value.slice(0,4))>9998||value===ministryMonth)return;ministryLoad(ministryPerson,value)}
function ministryCanClose(d){if(d.dataset.saving==='true'){d.querySelector('.ministry-sheet-error').textContent='저장 중이에요. 잠시만 기다려 주세요.';return false}return !d.isDirty?.()||confirm('변경한 내용이 저장되지 않았어요. 닫을까요?')}
function ministryRouteGuard(){const d=document.querySelector('.ministry-dialog[open]');if(location.hash==='#/ministry')return true;if(d){if(!ministryCanClose(d)){history.replaceState(history.state,'',location.pathname+location.search+'#/ministry');return false}d.dataset.routed='true';d.close()}ministryRequest++;return true}
function ministryDialog(markup,trigger){const d=document.createElement('dialog');d.className='ministry-dialog';d.innerHTML=markup;d.setAttribute('aria-label',d.querySelector('h2')?.textContent||'봉사 보고');document.body.append(d);d.requestCloseSafely=()=>{if(ministryCanClose(d))d.close()};d.addEventListener('cancel',e=>{e.preventDefault();d.requestCloseSafely()});d.addEventListener('close',()=>{d.remove();if(d.dataset.routed!=='true'&&trigger?.isConnected)trigger.focus()},{once:true});d.showModal();return d}
function ministryApplySaved(action,day,value,oldRevision,newRevision,person,month){if(location.hash!=='#/ministry'||ministryPerson!==person||ministryMonth!==month)return;if(!ministryReport||ministryReport.revision!==oldRevision){ministryLoad(person,month);return}if(action==='hours'){if(value)ministryReport.hours[String(day)]=value;else delete ministryReport.hours[String(day)]}else ministryReport.studies=value;ministryReport.revision=newRevision;ministryRender()}
async function ministryRefreshConflict(d,revisionSetter,describe){const button=d.querySelector('.ministry-refresh'),error=d.querySelector('.ministry-sheet-error');button.disabled=true;try{const latest=await ministryRead(ministryPerson,ministryMonth);if(!d.isConnected)return;ministryReport=latest;ministryRender();revisionSetter(latest.revision);error.textContent=describe(latest);button.hidden=true;d.querySelector('.ministry-save,.ministry-study-save').disabled=false}catch(err){error.textContent=ministryError(err)}finally{button.disabled=false}}

function ministryBurst(button,n){
 const layer=button.querySelector('.gem-effects');if(!layer||matchMedia('(prefers-reduced-motion: reduce)').matches)return;
 while(layer.children.length>=3)layer.firstElementChild.remove();
 const points=[[-25,-24],[25,-26],[-39,-7],[39,-10],[-15,-43],[16,-44],[-49,-23],[49,-26]],count=Math.min(2+Math.max(0,n-1),8),effect=document.createElement('span');
 effect.className='gem-pop gem-pop-v2';effect.setAttribute('aria-hidden','true');
 effect.innerHTML=MINISTRY_GEM+'<span class="gem-earned">+1</span>'+points.slice(0,count).map(([x,y],i)=>`<i class="gem-spark" style="--spark-x:${x}px;--spark-y:${y}px;--spark-delay:${i*22}ms"></i>`).join('');
 layer.append(effect);setTimeout(()=>effect.remove(),1050);
}
function ministryPulseNumber(element){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;element.classList.remove('ministry-number-earned');void element.offsetWidth;element.classList.add('ministry-number-earned')}

async function ministrySave(action,day,value,revision){const r=await rpc('study_ministry_write',{p_password:ministryPin,p_person:ministryPerson,p_month:ministryMonth,p_revision:revision,p_action:action,p_day:day,p_value:value});if(!r?.ok){let e=Error(r?.error||'저장하지 못했습니다.');e.conflict=!!r?.conflict;throw e}return r}
function ministryDayDialog(day,trigger){let draft=Number(ministryReport.hours?.[day]||0),initial=draft,revision=ministryReport.revision;const person=ministryPerson,month=ministryMonth;const m=Number(ministryMonth.slice(5));const d=ministryDialog(`<div class="ministry-sheet"><div class="ministry-sheet-head"><h2>${m}월 ${day}일</h2><button type="button" class="tool-icon" data-close aria-label="닫기">${uiIcon('<path d="M18 6 6 18M6 6l12 12"/>')}</button></div><div class="ministry-draft"><strong id="ministry-draft-value" aria-live="polite">${draft}</strong><span>시간</span></div><button type="button" class="gem-button" aria-label="봉사 시간 1시간 추가">${MINISTRY_GEM}<span class="gem-effects" aria-hidden="true"></span></button><div class="ministry-sheet-actions"><button type="button" class="tool-icon ministry-undo" aria-label="1시간 빼기" title="1시간 빼기">${uiIcon('<path d="M5 12h14"/>')}</button><button type="button" class="primary ministry-save">저장</button></div><p class="ministry-sheet-error" role="status"></p><button type="button" class="link ministry-refresh" hidden>최신 기록 다시 불러오기</button></div>`,trigger);const val=d.querySelector('#ministry-draft-value'),undo=d.querySelector('.ministry-undo'),gem=d.querySelector('.gem-button'),save=d.querySelector('.ministry-save'),error=d.querySelector('.ministry-sheet-error');function refresh(){val.textContent=draft;undo.disabled=draft===0;gem.disabled=draft>=24}refresh();d.isDirty=()=>draft!==initial;d.querySelector('[data-close]').onclick=()=>d.requestCloseSafely();gem.onclick=()=>{if(draft>=24)return;draft++;refresh();ministryPulseNumber(val);ministryBurst(gem,draft)};undo.onclick=()=>{if(draft>0){draft--;refresh()}};d.querySelector('.ministry-refresh').onclick=()=>ministryRefreshConflict(d,r=>revision=r,latest=>`최신 기록 ${Number(latest.hours?.[day]||0)}시간 · 입력한 값 ${draft}시간`);save.onclick=async()=>{save.disabled=true;gem.disabled=true;undo.disabled=true;d.dataset.saving='true';error.textContent='저장 중…';try{const old=revision,result=await ministrySave('hours',day,draft,revision);d.isDirty=()=>false;if(d.open)d.close();ministryApplySaved('hours',day,draft,old,result.revision,person,month)}catch(e){if(!d.isConnected)return;error.textContent=ministryError(e);if(e.conflict){save.disabled=true;d.querySelector('.ministry-refresh').hidden=false}else save.disabled=false;refresh()}finally{d.dataset.saving='false'}}}
function ministryStudiesDialog(trigger){let revision=ministryReport.revision;const person=ministryPerson,month=ministryMonth,value=ministryReport.studies===null?'':ministryReport.studies;const d=ministryDialog(`<form class="ministry-sheet ministry-study-form"><div class="ministry-sheet-head"><h2>성서 연구</h2><button type="button" class="tool-icon" data-close aria-label="닫기">${uiIcon('<path d="M18 6 6 18M6 6l12 12"/>')}</button></div><label class="ministry-studies-label">이번 달 연구 건수<input id="ministry-study-count" type="number" inputmode="numeric" min="0" max="9999" step="1" value="${value}"></label><p class="ministry-sheet-error" role="status"></p><button type="button" class="link ministry-refresh" hidden>최신 기록 다시 불러오기</button><button class="primary ministry-study-save">저장</button></form>`,trigger);const input=d.querySelector('input'),save=d.querySelector('.ministry-study-save'),error=d.querySelector('.ministry-sheet-error');d.isDirty=()=>input.value!==String(value);d.querySelector('[data-close]').onclick=()=>d.requestCloseSafely();d.querySelector('.ministry-refresh').onclick=()=>ministryRefreshConflict(d,r=>revision=r,latest=>`최신 기록 ${latest.studies===null?'미입력':latest.studies+'건'} · 입력한 값 ${input.value===''?'미입력':input.value+'건'}`);d.querySelector('form').onsubmit=async e=>{e.preventDefault();if(!input.checkValidity()){input.reportValidity();return}const value=input.value===''?null:Number(input.value);save.disabled=true;d.dataset.saving='true';error.textContent='저장 중…';try{const old=revision,result=await ministrySave('studies',null,value,revision);d.isDirty=()=>false;if(d.open)d.close();ministryApplySaved('studies',null,value,old,result.revision,person,month)}catch(err){if(!d.isConnected)return;error.textContent=ministryError(err);if(err.conflict)d.querySelector('.ministry-refresh').hidden=false;else save.disabled=false}finally{d.dataset.saving='false'}}}
